import sys

def find_mex(arr):
    mex = 0
    while mex in arr:
        mex += 1
    return mex

def construct_array(B):
    N = len(B)
    A = []
    used = set()

    for i in range(N):
        if B[i] != -1:
            mex = find_mex(used)
            if mex != B[i]:
                return -1
            A.append(mex)
            used.add(mex)
